// Cave Talk service worker -- generated by build.mjs, do not edit sw.js directly.
// Cache-first so the game opens instantly and works with no signal.
//
// NOTE: other games hosted on the same github.io origin keep their own caches, so
// we only ever create/delete caches prefixed "cave-talk-".
const CACHE = "cave-talk-__VERSION__";
const ASSETS = __ASSETS__;

self.addEventListener("install", (event) => {
  event.waitUntil(
    caches
      .open(CACHE)
      // cache: "reload" bypasses the browser HTTP cache so we always store fresh files
      .then((cache) => Promise.all(ASSETS.map((url) => cache.add(new Request(url, { cache: "reload" })))))
      .then(() => self.skipWaiting())
  );
});

self.addEventListener("activate", (event) => {
  event.waitUntil(
    caches
      .keys()
      .then((keys) =>
        Promise.all(keys.filter((k) => k.startsWith("cave-talk-") && k !== CACHE).map((k) => caches.delete(k)))
      )
      .then(() => self.clients.claim())
  );
});

self.addEventListener("fetch", (event) => {
  const req = event.request;
  if (req.method !== "GET") return;
  const url = new URL(req.url);
  if (url.origin !== self.location.origin) return;
  event.respondWith(
    caches.open(CACHE).then((cache) =>
      cache.match(req, { ignoreSearch: true }).then(
        (hit) =>
          hit ||
          fetch(req).catch(() =>
            req.mode === "navigate" ? cache.match("index.html") : Response.error()
          )
      )
    )
  );
});
